x <- strsplit(scan("stdin", what="", quiet=TRUE), "");a <- x[[1]];b <- x[[2]];digits <- c(as.character(0:9),letters[1:20]);val <- function(ch)match(ch,digits)-1L;i<-length(a);j<-length(b);carry<-0L;out<-character(max(i,j)+1L);pos<-length(out);while(i>0||j>0||carry>0){s<-carry;if(i>0)s<-s+val(a[i]);if(j>0)s<-s+val(b[j]);out[pos]<-digits[s%%30L+1L];carry<-s%/%30L;i<-i-1L;j<-j-1L;pos<-pos-1L};out<-out[(pos+1L):length(out)];first<-which(out!="0")[1];if(is.na(first))first<-length(out);out<-out[first:length(out)];cat(paste0(out,collapse=""),"\n")
